const STEPS = ["ready","sister_results_acquired","properties_extracted","owners_extracted","data_normalized","acquisition_reviewed","properties_processed","verified","completed"];
const PHASES = [
  { key:"prepare", label:"Preparazione", detail:"Apro e controllo i collegamenti" },
  { key:"read", label:"Leggo tutti i dati", detail:"Immobili, proprietari e quote da SISTER" },
  { key:"review", label:"Ti mostro il riepilogo", detail:"Controlli tutto prima di proseguire" },
  { key:"work", label:"Completo un immobile alla volta", detail:"Recapiti, proprietario con quota maggiore, immobile e attività" },
  { key:"finish", label:"Controllo e termino", detail:"Verifico che non manchi nulla" },
];
const GUIDE = {
  ready:{label:"Preparazione",doing:"Controllo che Chrome, SISTER, gestionale ed Excel siano raggiungibili.",next:"Quando tutto è pronto, ti chiederò di acquisire i risultati SISTER."},
  sister_results_acquired:{label:"Lettura SISTER",doing:"Sto leggendo la pagina dei risultati che hai già aperto.",next:"Individuerò solo gli immobili delle categorie A/ e C/."},
  properties_extracted:{label:"Raccolta immobili",doing:"Sto raccogliendo foglio, particella, subalterno, indirizzo e dati catastali.",next:"Per ogni immobile aprirò l’elenco dei proprietari."},
  owners_extracted:{label:"Raccolta proprietari",doing:"Sto leggendo nominativi, codici fiscali, diritti e quote di proprietà.",next:"Per ora lavorerò soltanto il nominativo con la quota più alta; gli altri resteranno salvati senza essere collegati."},
  data_normalized:{label:"Controllo dati",doing:"Sto uniformando codici fiscali, quote e chiavi catastali per evitare duplicati.",next:"Ti mostrerò un riepilogo completo prima del confronto col gestionale."},
  acquisition_reviewed:{label:"Riepilogo acquisizione",doing:"I dati SISTER sono raccolti. Attendo il tuo controllo del riepilogo.",next:"Dopo la conferma completerò il primo immobile con tutti i suoi proprietari, poi passerò al successivo."},
  properties_processed:{label:"Lavorazione degli immobili",doing:"Completo un immobile alla volta sotto il nominativo con la quota di proprietà più alta.",next:"Per questo immobile seguo sempre lo stesso ordine: recapiti Excel, proprietario principale, immobile e attività. I soggetti correlati restano sospesi."},
  person_searched:{label:"Ricerca nominativi",doing:"Cerco ogni persona nel gestionale prima per codice fiscale, poi per telefono e anagrafica.",next:"Se non esiste, preparerò una nuova scheda; se esiste, completerò solo i dati mancanti."},
  person_created_or_updated:{label:"Aggiornamento nominativi",doing:"Sto creando o aggiornando le schede delle persone senza duplicare i recapiti.",next:"Controllerò eventuali unioni proposte dal gestionale."},
  person_merge_reviewed:{label:"Controllo unioni",doing:"Verifico che gli eventuali merge del gestionale siano conclusi senza conflitti.",next:"Aprirò gli immobili collegati ai nominativi."},
  property_searched:{label:"Ricerca immobili",doing:"Cerco l’immobile dentro la scheda del proprietario, confrontando prima dati catastali e poi via e civico.",next:"Se lo trovo aggiorno i dati; altrimenti preparo una nuova scheda immobile."},
  property_created_or_updated:{label:"Aggiornamento immobili",doing:"Sto completando i dati catastali dell’immobile usando SISTER come fonte principale.",next:"Creerò una sola attività direttamente dalla scheda dell’immobile."},
  activity_created:{label:"Attività sugli immobili",doing:"Sto aggiungendo l’attività “Da eseguire” dalla scheda di ciascun immobile, non dal cliente.",next:"Poi abbinerò i recapiti del file Excel."},
  contacts_matched:{label:"Recapiti Excel",doing:"Cerco il codice fiscale nel file Excel e raccolgo telefoni ed email senza duplicati.",next:"Aggiungerò i recapiti mancanti alle persone già individuate."},
  owners_linked:{label:"Soggetti correlati sospesi",doing:"Conservo i comproprietari raccolti senza inserirli nel gestionale.",next:"Eseguirò l’ultimo controllo di completezza sul proprietario principale e sull’immobile."},
  verified:{label:"Verifica finale",doing:"Controllo che immobili, persone, attività, recapiti e quote siano stati elaborati.",next:"Se non manca nulla, il lavoro sarà concluso."},
  completed:{label:"Completato",doing:"La lavorazione è terminata e tutti i passaggi risultano salvati.",next:"Puoi aprire i dettagli oppure iniziare una nuova lavorazione."},
};
const ERROR_STATES=new Set(["needs_review","session_expired","portal_error","data_incomplete","failed"]);
let appState=null,checks=[],selectedMode="assisted",toastTimer=null,pendingCancelJobId=null,cancelInFlight=false,resolutionDetail=null,resolutionJobId=null,pendingPropertyRemovalId=null,propertyRemovalInFlight=false;
const $=id=>document.getElementById(id);
const esc=value=>String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const fmtTime=value=>value?new Intl.DateTimeFormat("it-IT",{hour:"2-digit",minute:"2-digit"}).format(new Date(value)):"—";
const fmtDate=value=>value?new Intl.DateTimeFormat("it-IT",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(value)):"—";
const guide=step=>GUIDE[step]??{label:String(step??"Elaborazione").replaceAll("_"," "),doing:"Il programma sta completando questo passaggio.",next:"L’avanzamento sarà salvato automaticamente."};
function toast(message){const el=$("toast");el.textContent=message;el.classList.add("is-visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("is-visible"),3500)}
function completedJobs(){return(appState?.completedImports??[]).map(item=>item.job)}
function currentJob(){return[...(appState?.jobs??[]),...completedJobs()].find(job=>job.id===appState?.activeJobId)}

function errorAdvice(job,error){const raw=String(error??job?.error_message??"");const text=raw.toLowerCase();const status=job?.status,details=job?.error_details??{},portalAction=String(details.action??""),operation=String(details.operationLabel??"");
  if(portalAction==="job-graph-integrity"||portalAction==="job-ownership-integrity"||text.includes("006_property_worker_archives"))return{cause:"L’archivio dati non è ancora aggiornato alla versione richiesta dal programma.",steps:["Non riprendere questa lavorazione: il programma l’ha fermata prima di modificare il gestionale.","Applica la migration 006_property_worker_archives.sql al progetto Supabase condiviso.","Dopo l’aggiornamento avvia una nuova acquisizione SISTER: i vecchi lavori incompleti non verranno riutilizzati."],action:"schema",operation:operation||"Controllo integrità della lavorazione"};
  if(portalAction==="person-multiple-exact-matches")return{cause:"Nel gestionale esistono più schede con lo stesso codice fiscale.",steps:["Apri la scheda nominativo corretta nel gestionale.","Controlla che nome e codice fiscale coincidano con SISTER.","Premi “Ho scelto la scheda corretta, continua”: il programma userà quella aperta e passerà direttamente all’immobile."],action:"selected-person",operation:operation||"Scelta del nominativo esistente"};
  if(portalAction==="person-field-missing"&&details.selectorKey==="personFirstName")return{cause:"Il programma ha confuso la scheda di un nominativo già esistente con la finestra per crearne uno nuovo.",steps:["Non devi compilare nuovamente il nominativo.","Lascia aperta la sua scheda nel gestionale.","Premi “Riprova questo passaggio”: la versione aggiornata riconoscerà la scheda e passerà direttamente all’immobile."],action:"portal",operation:operation||"Passaggio dal nominativo all’immobile"};
  if(portalAction.startsWith("phone-")||portalAction.startsWith("person-contact-"))return{cause:"Il gestionale non ha completato la verifica o l’assegnazione dei recapiti.",steps:["Lascia aperta la scheda del nominativo.","Il programma controllerà di nuovo i recapiti già presenti senza ricreare la persona.","Se il numero appartiene a un’altra scheda, lo sposterà automaticamente quando la corrispondenza è univoca."],action:"portal",operation:operation||"Verifica recapiti Excel"};
  if(portalAction.startsWith("person-property-")||portalAction.startsWith("property-"))return{cause:"Il gestionale non ha completato il passaggio relativo all’immobile.",steps:["Lascia aperta la scheda attuale.","Premi “Riprova questo passaggio”: il programma riaprirà il nominativo o l’immobile corretto usando l’identificativo salvato.","Se continua a non riuscire, usa “Salta immobile” per proseguire con gli altri."],action:"portal",operation:operation||"Ricerca o compilazione immobile"};
  if(portalAction.startsWith("activity-"))return{cause:"La finestra dell’attività non ha terminato il caricamento o non ha confermato il salvataggio.",steps:["Non creare l’attività dal nominativo: il programma la riaprirà dalla scheda dell’immobile.","Lascia il gestionale aperto e riprova.","Prima di salvare, il programma ricontrollerà immobile collegato, descrizione e stato."],action:"portal",operation:operation||"Attività dall’immobile"};
  if(status==="session_expired"||text.includes("sessione")&&text.includes("scad"))return{cause:"La sessione del portale non è più valida.",steps:["Apri Chrome di lavoro.","Accedi di nuovo al portale indicato, senza chiudere la scheda.","Torna qui e premi “Ho effettuato l’accesso, riprendi”."],action:"session"};
  if(status==="data_incomplete"||text.includes("mancant")||text.includes("quota"))return{cause:"Uno o più dati indispensabili non sono disponibili o non sono leggibili con certezza.",steps:["Apri “Correggi dati qui sotto”.","Compila i campi evidenziati usando il dato visibile su SISTER.","Salva e riprendi: il programma continuerà dal passaggio successivo."],action:"data"};
  if(status==="needs_review"||text.includes("più")||text.includes("merge"))return{cause:"Il programma ha trovato più possibilità e non vuole scegliere quella sbagliata.",steps:["Controlla nel gestionale quale scheda è corretta.","Se serve, completa il merge o la scelta manualmente.","Premi “Ho risolto nel gestionale, riprendi”."],action:"review"};
  if(status==="portal_error"&&(text.includes("campo")||text.includes("luogo di nascita")||text.includes("sesso")))return{cause:raw,steps:["Lascia aperta la finestra Nominativo così com’è.","Premi “Riprova questo passaggio”: il programma riutilizzerà la finestra già aperta.","Se il gestionale mostra più alternative per il luogo di nascita, scegli quella corretta e riprendi."],action:"portal"};
  if(text.includes("selector")||text.includes("locator")||text.includes("pagina")||status==="portal_error")return{cause:"La pagina del portale è diversa da quella attesa oppure c’è una finestra aperta che copre i comandi.",steps:["Lascia aperta la pagina indicata nel gestionale o in SISTER.","Chiudi eventuali messaggi o finestre rimaste a metà.","Premi “Riprova questo passaggio”. Se manca un valore, puoi inserirlo dall’app."],action:"portal"};
  return{cause:"Si è verificato un problema inatteso, ma l’avanzamento precedente è al sicuro.",steps:["Premi “Controlla collegamenti”.","Se tutti i controlli sono verdi, riprova il passaggio.","Se manca un dato, usa “Correggi dati qui sotto”."],action:"unknown"};
}

function renderChecks(){const wanted=[["chrome","Chrome"],["sister","SISTER"],["crm","Gestionale"],["excel","File Excel"],["supabase","Archivio dati"]];$("checksGrid").innerHTML=wanted.map(([id,label])=>{const keep=appState?.sisterKeepAlive;const keepResult=id==="sister"&&!["waiting","disabled"].includes(keep?.statusLabel)?{ok:keep.ok,detail:keep.ok?`Sessione attiva · ${fmtTime(keep.checkedAt)}`:keep.message}:null;const result=keepResult??checks.find(x=>x.id===id);return`<div class="check-item ${result?(result.ok?"is-ok":"is-error"):""}"><span></span><div><b>${label}</b><small title="${esc(result?.detail??"Da controllare")}">${esc(result?.detail??"Da controllare")}</small></div></div>`}).join("")}
function currentPhase(step){if(step==="ready")return 0;if(["sister_results_acquired","properties_extracted","owners_extracted","data_normalized"].includes(step))return 1;if(step==="acquisition_reviewed")return 2;if(step==="properties_processed"||["person_searched","person_created_or_updated","person_merge_reviewed","property_searched","property_created_or_updated","activity_created","contacts_matched","owners_linked"].includes(step))return 3;return 4}
function nextStepName(last){const index=STEPS.indexOf(last);return index<0?"properties_processed":STEPS[Math.min(index+1,STEPS.length-1)]}
function renderSteps(){const job=appState?.jobs?.find(j=>j.id===appState.activeJobId);const current=appState?.currentStep??job?.current_step??"ready",phase=currentPhase(current),done=current==="completed";let percent=[0,15,40,50,95][phase]??0;const p=appState?.propertyProgress;if(current==="properties_processed"&&p?.total)percent=Math.round(50+((p.index-1+(p.stage==="completed"?1:0))/p.total)*40);if(done)percent=100;$("progressPercent").textContent=`${percent}%`;$("progressBar").style.width=`${percent}%`;$("workflowSteps").innerHTML=PHASES.map((item,i)=>`<li class="workflow-step ${done||i<phase?"is-done":i===phase?"is-current":""}"><span class="index">${done||i<phase?"✓":i+1}</span><b>${esc(item.label)}<small>${esc(item.detail)}</small></b></li>`).join("")}
function cancelButton(jobId){return jobId?`<button class="button danger" data-cancel-job="${esc(jobId)}">Annulla lavoro</button>`:""}
function promptButtons(prompt){if(prompt.kind==="merge")return`<button class="button primary" data-prompt="confirm">Il merge è corretto</button><button class="button secondary" data-prompt="manual">Lo sistemo manualmente</button>`;if(prompt.kind==="decision")return`<button class="button primary" data-prompt="confirm">Conferma</button><button class="button secondary" data-prompt="skip">Salta questo caso</button><button class="button secondary" data-prompt="manual">Modifico nel gestionale</button><button class="button danger" data-prompt="review">Segna da verificare</button>`;return`<button class="button primary" data-prompt="confirm">${prompt.kind==="acquisition"?"Acquisisci risultati":"Ho terminato, continua"}</button>`}
function renderAction(){const panel=$("actionPanel"),job=currentJob(),completed=job?.status==="completed"||appState?.currentStep==="completed";
  if(appState?.configError){panel.className="now-card is-error";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Configurazione necessaria</div><h2>Completa una sola volta le impostazioni</h2><p>Il programma non ha trovato la configurazione interna. Non serve creare un file: inserisci i valori nella sezione avanzata e Windows li proteggerà.</p><div class="now-actions"><button class="button primary" data-action="config">Apri impostazioni</button></div></div><div class="now-side"><h3>Cosa manca</h3><p>${esc(appState.configError)}</p></div></div>`;return}
  if(appState?.cancellingJobId){panel.className="now-card is-warning";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Arresto sicuro</div><h2>Sto annullando la lavorazione</h2><p>Attendo la fine dell’operazione già iniziata, poi elimino i dati del lavoro.</p></div><div class="now-side"><b>Non chiudere l’app.</b><p>Ti avviserò appena l’annullamento è concluso.</p></div></div>`;return}
  if(appState?.prompt){if(appState.prompt.kind==="acquisition-review"){panel.className="now-card";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Dati raccolti</div><h2>Controlla immobili e proprietari</h2><p>La raccolta da SISTER è finita. Prima di toccare il gestionale, verifica il riepilogo.</p><div class="now-actions"><button class="button primary" data-action="open-review">Apri il riepilogo</button>${cancelButton(appState.activeJobId)}</div></div><div class="now-side"><h3>Dopo la conferma</h3><p>Inizierò a cercare i nominativi nel gestionale.</p></div></div>`;return}panel.className="now-card is-warning";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Serve una tua conferma</div><h2>${esc(appState.prompt.title)}</h2><p>${esc(appState.prompt.summary)}</p><div class="now-actions">${promptButtons(appState.prompt)}${cancelButton(appState.activeJobId)}</div></div><div class="now-side"><h3>Perché mi sono fermato?</h3><p>Questa scelta può modificare dati nel gestionale. Attendo la tua decisione per sicurezza.</p></div></div>`;return}
  if(completed){const properties=job?.processed_properties??job?.total_properties??0,people=job?.processed_people??job?.total_people??0;panel.className="now-card is-success";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span>✓</span>Import concluso</div><h2>Import eseguito con successo</h2><p>Il gestionale è stato aggiornato e tutti i passaggi risultano completati.</p><div class="success-summary"><b>${properties} immobili completati</b><b>${people} nominativi elaborati</b></div><div class="now-actions"><button class="button primary" data-scroll="completedImports">Vedi cosa è stato importato</button></div></div><div class="now-side"><h3>Nessuna azione richiesta</h3><p>Il lavoro è memorizzato nella sezione “Import effettuati con successo”. Puoi iniziare una nuova lavorazione.</p></div></div>`;return}
  if(appState?.lastError){const advice=errorAdvice(job,appState.lastError),last=guide(job?.last_completed_step),next=guide(nextStepName(job?.last_completed_step)),property=job?.error_details?.propertyAddress,operation=advice.operation??job?.error_details?.operationLabel;panel.className="now-card is-error";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Lavorazione ferma, dati salvati</div><h2>${esc(advice.cause)}</h2>${operation?`<p><b>Cosa stavo facendo:</b> ${esc(operation)}${property?` su ${esc(property)}`:""}.</p>`:""}<p>Ultimo punto concluso: <b>${esc(last.label)}</b>. Ripartirò da <b>${esc(next.label)}</b>, senza ricominciare.</p><div class="recovery-box"><b>Cosa fare adesso</b><ol>${advice.steps.map(x=>`<li>${esc(x)}</li>`).join("")}</ol></div><div class="now-actions">${advice.action==="data"||advice.action==="unknown"?`<button class="button primary" data-action="open-corrections">Correggi dati qui sotto</button>`:""}<button class="button ${advice.action==="data"?"secondary":"primary"}" data-action="resume-current">${advice.action==="session"?"Ho effettuato l’accesso, riprendi":advice.action==="review"?"Ho risolto nel gestionale, riprendi":advice.action==="selected-person"?"Ho scelto la scheda corretta, continua":"Riprova questo passaggio"}</button><button class="button secondary" data-action="checks">Controlla collegamenti</button>${cancelButton(appState.activeJobId)}</div><details class="technical-details"><summary>Dettaglio tecnico per assistenza</summary><pre>${esc(appState.lastError)}</pre></details></div><div class="now-side"><h3>Il lavoro è al sicuro</h3><p>Ogni passaggio concluso è stato salvato. La ripresa riapre le schede tramite i loro identificativi e non ricrea ciò che è già completo.</p></div></div>`;return}
  const current=guide(appState?.currentStep??"ready");if(appState?.active){const progress=appState.propertyProgress;const propertyContext=appState.currentStep==="properties_processed"&&progress?`<span class="property-position">Immobile ${progress.index} di ${progress.total}</span><h2>${esc(progress.address??"Immobile senza indirizzo")}</h2><p><b>${esc(progress.message)}</b></p>`:`<h2>${esc(current.label)}</h2><p>${esc(current.doing)}</p>`;panel.className="now-card";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Sto lavorando adesso</div>${propertyContext}<div class="now-actions"><button class="button secondary" data-action="pause">Metti in pausa</button>${cancelButton(appState.activeJobId)}</div></div><div class="now-side"><h3>${progress?"Ordine per questo immobile":"Cosa succede dopo"}</h3>${progress?"<ol><li>Recapiti dal file Excel</li><li>Anagrafica del proprietario</li><li>Immobile collegato</li><li>Attività dall’immobile</li><li>Comproprietari e quote</li></ol>":`<p>${esc(current.next)}</p>`}<p><b>Non devi fare nulla</b> finché non compare una richiesta.</p></div></div>`;return}
  panel.className="now-card";panel.innerHTML=`<div class="now-grid"><div class="now-main"><div class="now-label"><span></span>Pronto per iniziare</div><h2>Apri le due schede nel Chrome di lavoro</h2><p>Accedi manualmente a SISTER e al gestionale. Su SISTER scegli Comune, via e civico, poi avvia la ricerca e lascia visibili i risultati.</p><div class="now-actions"><button class="button primary" data-action="checks">Controlla se è tutto pronto</button></div></div><div class="now-side"><h3>In tre mosse</h3><ol><li>Apri Chrome di lavoro.</li><li>Porta SISTER sui risultati.</li><li>Premi “Inizia lavorazione”.</li></ol></div></div>`}

function renderJobs(){const jobs=appState?.jobs??[];$("jobCount").textContent=jobs.length;$("jobsList").innerHTML=jobs.length?jobs.map(job=>{const canImport=!appState.active&&job.status!=="completed",place=[job.municipality,job.street,job.civic_number].filter(Boolean).join(" · ")||`Ricerca ${job.id.slice(0,8)}`,imported=job.status==="completed",inProgress=Boolean(job.import_started_at)&&!imported;return`<article class="job-item ${imported?"is-completed":inProgress?"is-running":""}"><span></span><div><b>${esc(place)}</b><small>${job.total_properties??0} immobili · ${job.total_people??0} proprietari · salvata ${fmtDate(job.saved_at??job.created_at)}<br>${imported?"Importazione completata":inProgress?`Importazione iniziata · ultimo punto: ${esc(guide(job.last_completed_step??"acquisition_reviewed").label)}`:"Pronta per essere importata senza rileggere SISTER"}</small></div><div class="job-actions"><button class="text-button" data-detail-job="${job.id}">Apri dati</button>${canImport?`<button class="text-button" data-resume-job="${job.id}">${inProgress?"Continua importazione":"Importa"}</button>`:""}<button class="text-button is-destructive" data-cancel-job="${job.id}">Elimina</button></div></article>`}).join(""):`<p class="empty-message">Nessuna ricerca salvata. Dopo la lettura SISTER potrai conservarla qui e importarla quando vuoi.</p>`}
function renderCompletedImports(){const imports=appState?.completedImports??[];$("completedImportCount").textContent=imports.length;$("completedImportsList").innerHTML=imports.length?imports.map(item=>{const job=item.job,place=[job.municipality,job.street,job.civic_number].filter(Boolean).join(" · ")||`Import ${job.id.slice(0,8)}`;return`<section class="completed-import"><header><div><span class="completed-check">✓</span><div><h3>${esc(place)}</h3><p>Concluso ${fmtDate(job.completed_at??job.updated_at)} · ${item.properties.length} immobili · ${item.people.length} nominativi</p></div></div><button class="text-button" data-detail-job="${job.id}">Apri riepilogo</button></header><div class="completed-property-list">${item.properties.map((property,index)=>{const related=item.ownerships.filter(owner=>owner.property_id===property.id).map(owner=>({owner,person:item.people.find(person=>person.id===owner.person_id)})).filter(entry=>entry.person);const activity=property.raw_payload?.worker_activity?.state;return`<article class="completed-property-card"><div class="completed-owners"><p class="eyebrow">Nominativi · ${related.length}</p>${related.map(({owner,person})=>`<div class="completed-owner"><div><strong>${esc(person.full_name)}</strong><span>${owner.share_percentage==null?"Quota non disponibile":`${new Intl.NumberFormat("it-IT").format(owner.share_percentage)}%`}</span></div><small>${esc(person.tax_code??"Codice fiscale non disponibile")}</small><small>${esc([person.birth_place,person.birth_date].filter(Boolean).join(" · ")||"Dati di nascita non disponibili")}</small><small>${esc([...(person.mobiles??[]),...(person.landlines??[]),...(person.emails??[])].join(" · ")||"Nessun recapito trovato")}</small></div>`).join("")||`<p class="empty-message">Nessun nominativo collegato.</p>`}</div><div class="completed-property-data"><div class="completed-property-heading"><p class="eyebrow">Immobile ${index+1}</p><span class="completion-label">Completato</span></div><h3>${esc(property.address??"Indirizzo non disponibile")}</h3><p class="cadastral-key">${esc(property.cadastral_key)}</p><dl><div><dt>Categoria</dt><dd>${esc(property.category??"—")}</dd></div><div><dt>Consistenza</dt><dd>${esc(property.consistency??"—")}</dd></div><div><dt>Rendita</dt><dd>${property.cadastral_income==null?"—":new Intl.NumberFormat("it-IT",{style:"currency",currency:"EUR"}).format(property.cadastral_income)}</dd></div><div><dt>Attività</dt><dd>${activity==="created"?"Creata":activity==="existing"?"Già presente":"Verificata"}</dd></div></dl></div></article>`}).join("")}</div></section>`}).join(""):`<div class="completed-empty"><span>✓</span><div><b>Nessun import concluso</b><p>Quando una lavorazione termina correttamente, troverai qui immobili, nominativi e quote.</p></div></div>`}
function isSkippedProperty(property){return property?.processing_status==="skipped"||property?.raw_payload?.property_flow?.stage==="skipped"}
function completedSessionStats(item){const skippedProperties=(item.properties??[]).filter(isSkippedProperty),skippedIds=new Set(skippedProperties.map(property=>property.id)),skippedPeople=new Set((item.ownerships??[]).filter(owner=>skippedIds.has(owner.property_id)).map(owner=>owner.person_id));return{completedProperties:(item.properties??[]).length-skippedProperties.length,skippedProperties:skippedProperties.length,skippedPeople:skippedPeople.size}}
function renderCompletedSessions(){const imports=appState?.completedImports??[];$("completedImportCount").textContent=imports.length;$("completedImportsList").innerHTML=imports.length?imports.map(item=>{const job=item.job,place=[job.municipality,job.street,job.civic_number].filter(Boolean).join(" · ")||`Import ${job.id.slice(0,8)}`,stats=completedSessionStats(item),skipText=stats.skippedProperties?` · ${stats.skippedProperties} immobili e ${stats.skippedPeople} nominativi saltati`:"";return`<article class="completed-session ${stats.skippedProperties?"has-skipped":""}"><span class="completed-check">${stats.skippedProperties?"!":"✓"}</span><div><p class="eyebrow">Sessione conclusa</p><h3>${esc(place)}</h3><p>${fmtDate(job.completed_at??job.updated_at)} · ${stats.completedProperties} immobili completati${skipText}</p></div><button class="button secondary" data-completed-session="${job.id}">Apri sessione</button></article>`}).join(""):`<div class="completed-empty"><span>✓</span><div><b>Nessun import concluso</b><p>Le sessioni completate compariranno qui.</p></div></div>`;const more=$("completedImportsLoadMore");more.classList.toggle("is-hidden",!appState?.completedImportsHasMore);enhanceActionPanel()}
function completedPropertyCards(detail){return(detail.properties??[]).map((property,index)=>{const related=(detail.ownerships??[]).filter(owner=>owner.property_id===property.id).map(owner=>({owner,person:(detail.people??[]).find(person=>person.id===owner.person_id)})).filter(entry=>entry.person),activity=property.raw_payload?.worker_activity?.state,skipped=isSkippedProperty(property),skip=property.raw_payload?.skip_details??{},attempts=Number(skip.attempts??0),automatic=skip.source==="automatic",statusLabel=skipped?(automatic?`Saltato dopo ${attempts} tentativi`:"Saltato manualmente"):"Completato",reason=String(skip.reason??"Caso non completato");return`<article class="completed-property-card ${skipped?"is-skipped":""}"><div class="completed-owners"><p class="eyebrow">${skipped?"Nominativi saltati":"Nominativi"} · ${related.length}</p>${related.map(({owner,person})=>`<div class="completed-owner"><div><strong>${esc(person.full_name)}</strong><span>${owner.share_percentage==null?"Quota non disponibile":`${new Intl.NumberFormat("it-IT").format(owner.share_percentage)}%`}</span></div><small>${esc(person.tax_code??"Codice fiscale non disponibile")}</small><small>${esc([...(person.mobiles??[]),...(person.landlines??[]),...(person.emails??[])].join(" · ")||"Nessun recapito trovato")}</small>${skipped?`<small class="skipped-person-note">Non completato in questa importazione</small>`:""}</div>`).join("")||`<p class="empty-message">Nessun nominativo collegato.</p>`}</div><div class="completed-property-data"><div class="completed-property-heading"><p class="eyebrow">Immobile ${index+1}</p><span class="completion-label ${skipped?"is-skipped":""}">${esc(statusLabel)}</span></div><h3>${esc(property.address??"Indirizzo non disponibile")}</h3><p class="cadastral-key">${esc(property.cadastral_key)}</p>${skipped?`<div class="skip-summary"><b>Perché è stato saltato</b><p>${esc(reason)}</p>${automatic?`<small>Tre tentativi automatici eseguiti in circa 180 secondi.</small>`:""}</div>`:""}<dl><div><dt>Sezione urbana</dt><dd>BA</dd></div><div><dt>Foglio</dt><dd>${esc(property.sheet)}</dd></div><div><dt>Particella</dt><dd>${esc(property.parcel)}</dd></div><div><dt>Subalterno</dt><dd>${esc(property.subaltern)}</dd></div><div><dt>Categoria</dt><dd>${esc(property.category??"—")}</dd></div><div><dt>Rendita</dt><dd>${property.cadastral_income==null?"—":new Intl.NumberFormat("it-IT",{style:"currency",currency:"EUR"}).format(property.cadastral_income)}</dd></div><div><dt>Attività</dt><dd>${skipped?"Non completata":activity==="created"?"Creata":activity==="existing"?"Già presente":"Verificata"}</dd></div></dl></div></article>`}).join("")}
function enhanceActionPanel(){const actions=$("actionPanel")?.querySelector(".now-actions");if(!actions)return;const progress=appState?.propertyProgress,jobId=appState?.activeJobId;if(progress&&jobId&&!actions.querySelector("[data-skip-property]"))actions.insertAdjacentHTML("beforeend",`<button class="button danger" data-skip-property="${esc(progress.propertyId)}" data-job-id="${esc(jobId)}">Salta immobile</button>`);const side=$("actionPanel")?.querySelector(".now-side");if(appState?.active&&progress&&side&&!side.querySelector(".automation-plan"))side.insertAdjacentHTML("beforeend",`<div class="automation-plan"><b>Controlli automatici inclusi</b><p>Verifico e, se necessario, sposto i recapiti dal vecchio nominativo a quello corretto. Compilo anche sezione urbana BA, foglio, particella, subalterno e rendita.</p></div>`);if(appState?.lastError&&!actions.querySelector('[data-action="toggle-auto-retry"]'))actions.insertAdjacentHTML("beforeend",`<button class="button secondary" data-action="toggle-auto-retry">${appState.autoRetryEnabled===false?"Riattiva riprova automatico":"Ferma riprova automatico"}</button>`);if(appState?.lastError&&!$("#autoRetryCountdown")){const details=$("actionPanel").querySelector(".technical-details");const notice=document.createElement("p");notice.id="autoRetryCountdown";notice.className="auto-retry-notice";(details??actions).insertAdjacentElement(details?"beforebegin":"afterend",notice);updateAutoRetryCountdown()}}
function updateAutoRetryCountdown(){const el=$("autoRetryCountdown");if(!el)return;if(appState?.autoRetryEnabled===false){el.textContent="Riprova automatico fermato. Il lavoro ripartirà soltanto quando premi tu “Riprova questo passaggio” oppure lo riattivi.";return}const due=appState?.autoRetry?.dueAt;if(!due){el.textContent="Riprova automatico attivo: il prossimo tentativo verrà programmato se il passaggio resta fermo.";return}const seconds=Math.max(0,Math.ceil((new Date(due).getTime()-Date.now())/1000)),attempt=appState.autoRetry?.attempt??1;el.textContent=seconds?`Tentativo automatico ${attempt} di 3 tra ${seconds} secondi. Se anche il terzo fallisce, salto questo immobile e i suoi nominativi e continuo.`:"Riprova automatica in avvio…"}
