function renderReview(){const dialog=$("acquisitionReviewDialog"),review=appState?.prompt?.kind==="acquisition-review"?appState.prompt.review:null;if(!review){if(dialog.open)dialog.close();return}$("acquisitionReviewContext").textContent=[review.municipality,review.street,review.civicNumber].filter(Boolean).join(" · ")||"Risultati acquisiti";$("acquisitionReviewCount").textContent=`${review.properties.length} immobili`;$("acquisitionReviewContent").innerHTML=review.properties.map((p,i)=>`<article class="review-property"><section class="review-owners"><p class="eyebrow">Proprietari · ${p.owners.length}</p>${p.owners.map(o=>`<div class="review-owner"><div><strong>${esc(o.fullName)}</strong><small>${esc(o.taxCode??"CF mancante")}</small></div><div><span>${esc([o.birthPlace,o.birthDate].filter(Boolean).join(" · ")||"Nascita non disponibile")}</span><b>${o.sharePercentage==null?"Quota n/d":`${new Intl.NumberFormat("it-IT").format(o.sharePercentage)}%`}</b></div></div>`).join("")||"Nessun proprietario"}</section><section class="review-property-data"><p class="eyebrow">Immobile ${i+1}</p><h3>${esc(p.address??"Indirizzo non disponibile")}</h3><p>${esc(p.cadastralKey)}</p><dl><div><dt>Categoria</dt><dd>${esc(p.category??"—")}</dd></div><div><dt>Classe</dt><dd>${esc(p.class??"—")}</dd></div><div><dt>Consistenza</dt><dd>${esc(p.consistency??"—")}</dd></div><div><dt>Rendita</dt><dd>${p.cadastralIncome==null?"—":new Intl.NumberFormat("it-IT",{style:"currency",currency:"EUR"}).format(p.cadastralIncome)}</dd></div></dl></section></article>`).join("");if(!dialog.open)dialog.showModal()}

