async function loadResolution(jobId,show=true){resolutionJobId=jobId;resolutionDetail=await window.propertyWorker.getJobDetails(jobId);if(show){renderCorrections();$("manualCorrectionPanel").scrollIntoView({behavior:"smooth",block:"start"})}}
function nullableNumber(value){return value.trim()===""?null:Number(value.replace(",","."))}

function render(){if(!appState)return;selectedMode=appState.preferences?.mode??selectedMode;const job=currentJob(),completed=job?.status==="completed"||appState.currentStep==="completed";document.querySelectorAll("[data-mode]").forEach(b=>b.classList.toggle("is-selected",b.dataset.mode===selectedMode));$("modeHelp").textContent=selectedMode==="automatic"?"Procede da solo e si ferma solo quando non può scegliere in sicurezza.":"Ti chiede conferma prima dei salvataggi.";$("dryRunToggle").checked=appState.preferences?.dryRun!==false;$("versionLabel").textContent=`v${appState.version}`;$("excelPath").textContent=appState.config?.contactsExcelPath??appState.preferences?.contactsExcelPath??"Nessun file selezionato";$("screenshotPath").textContent=appState.config?.screenshotDirectory??"Gestito automaticamente";$("keepAliveStatus").textContent=appState.sisterKeepAlive?.statusLabel==="active"?`Attivo · ultimo controllo ${fmtTime(appState.sisterKeepAlive.checkedAt)}`:appState.sisterKeepAlive?.message??"In attesa";$("configurationStatus").textContent=appState.configError?"Da completare":appState.config?.configurationSource??"Pronta";$("configurationStatus").className=`status-pill ${appState.configError?"is-error":"is-complete"}`;$("startButton").disabled=appState.active||Boolean(appState.configError)||Boolean(appState.lastError&&appState.activeJobId&&!completed);$("runBadge").className=`status-pill ${appState.active?"is-running":completed?"is-complete":appState.lastError?"is-error":"is-idle"}`;$("runBadge").innerHTML=`<span></span>${appState.active?"In lavorazione":completed?"Completata":appState.lastError?"Serve attenzione":"Pronto"}`;$("operationTitle").textContent=appState.active?guide(appState.currentStep).label:completed?"Import completato":"Percorso completo";renderChecks();renderSteps();renderAction();renderJobs();renderCompletedImports();renderActivity();renderReview();renderSoftwareUpdate()}
async function runChecks(){$("checkButton").disabled=true;$("lastCheckLabel").textContent="Sto controllando…";try{checks=await window.propertyWorker.runChecks();const ok=checks.every(x=>x.ok);$("lastCheckLabel").textContent=ok?"Tutto pronto":"Controlla gli elementi rossi";renderChecks();toast(ok?"Tutto pronto per partire":"Ci sono collegamenti da sistemare")}catch(e){toast(e.message??String(e))}finally{$("checkButton").disabled=false}}
function openCancel(jobId){if(!jobId)return;pendingCancelJobId=jobId;cancelInFlight=false;const d=$("cancelProcessDialog");d.querySelectorAll("button").forEach(b=>b.disabled=false);d.showModal()}

document.addEventListener("click",async event=>{const target=event.target.closest("button");if(!target)return;try{
  if(target.dataset.updateAction==="check")await window.propertyWorker.checkUpdate();
  else if(target.dataset.updateAction==="download")await window.propertyWorker.downloadUpdate();
  else if(target.dataset.updateAction==="install")await window.propertyWorker.installUpdate();
  else if(target.dataset.scroll)document.getElementById(target.dataset.scroll)?.scrollIntoView({behavior:"smooth"});
  else if(target.dataset.mode){selectedMode=target.dataset.mode;await window.propertyWorker.savePreferences({mode:selectedMode})}
  else if(target.id==="checkButton"||target.dataset.action==="checks")await runChecks();
  else if(target.id==="chromeButton"){await window.propertyWorker.openChrome();toast("Chrome di lavoro aperto")}
  else if(target.id==="chooseExcelButton"){const path=await window.propertyWorker.chooseExcel();if(path)toast("File Excel aggiornato")}
  else if(target.id==="startButton")await window.propertyWorker.startJob({mode:selectedMode,dryRun:$("dryRunToggle").checked});
  else if(target.dataset.action==="toggle-auto-retry"){const enabling=appState.autoRetryEnabled===false;await window.propertyWorker.setAutoRetryEnabled(enabling);toast(enabling?"Riprova automatico riattivato":"Riprova automatico fermato")}
  else if(target.dataset.action==="pause")await window.propertyWorker.pauseJob();
  else if(target.dataset.skipProperty&&target.dataset.jobId){await window.propertyWorker.skipProperty({jobId:target.dataset.jobId,propertyId:target.dataset.skipProperty});toast("Immobile saltato: continuo con il successivo")}
  else if(target.id==="completedImportsLoadMore")await window.propertyWorker.loadMoreCompleted();
  else if(target.dataset.completedSession){const detail=await window.propertyWorker.getJobDetails(target.dataset.completedSession),job=detail.job,place=[job.municipality,job.street,job.civic_number].filter(Boolean).join(" · ")||`Import ${job.id.slice(0,8)}`,stats=completedSessionStats(detail),skipText=stats.skippedProperties?` · ${stats.skippedProperties} immobili e ${stats.skippedPeople} nominativi saltati`:"";$("completedImportDialogTitle").textContent=place;$("completedImportDialogMeta").textContent=`Concluso ${fmtDate(job.completed_at??job.updated_at)} · ${stats.completedProperties} immobili completati${skipText}`;$("completedImportDialogContent").innerHTML=completedPropertyCards(detail);$("completedImportDialog").showModal()}
  else if(target.dataset.action==="close-completed-session")$("completedImportDialog").close();
  else if(target.dataset.action==="resume-current"&&appState.activeJobId)await window.propertyWorker.resumeJob(appState.activeJobId);
  else if(target.dataset.resumeJob)await window.propertyWorker.resumeJob(target.dataset.resumeJob);
  else if(target.dataset.fixJob)await loadResolution(target.dataset.fixJob);
  else if(target.dataset.action==="open-corrections"&&appState.activeJobId)await loadResolution(appState.activeJobId);
  else if(target.dataset.action==="close-corrections")$("manualCorrectionPanel").classList.add("is-hidden");
  else if(target.dataset.removeProperty){pendingPropertyRemovalId=target.dataset.removeProperty;renderCorrections();target.closest(".manual-property-card")?.scrollIntoView({behavior:"smooth",block:"nearest"})}
  else if(target.hasAttribute("data-cancel-property-removal")){pendingPropertyRemovalId=null;renderCorrections()}
  else if(target.dataset.confirmPropertyRemoval&&resolutionJobId&&!propertyRemovalInFlight){propertyRemovalInFlight=true;renderCorrections();try{await window.propertyWorker.removeJobProperty({jobId:resolutionJobId,propertyId:target.dataset.confirmPropertyRemoval});pendingPropertyRemovalId=null;resolutionDetail=await window.propertyWorker.getJobDetails(resolutionJobId);toast("Immobile rimosso dalla lavorazione")}finally{propertyRemovalInFlight=false;renderCorrections()}}
  else if(target.dataset.action==="config"){document.getElementById("advancedConfiguration").open=true;document.getElementById("settings").scrollIntoView({behavior:"smooth"})}
  else if(target.dataset.action==="open-review")renderReview();
  else if(target.dataset.reviewDecision&&appState?.prompt){$("acquisitionReviewDialog").close();await window.propertyWorker.answerPrompt({promptId:appState.prompt.id,decision:target.dataset.reviewDecision})}
  else if(target.dataset.prompt&&appState?.prompt)await window.propertyWorker.answerPrompt({promptId:appState.prompt.id,decision:target.dataset.prompt==="confirm"&&["acquisition","manual"].includes(appState.prompt.kind)?undefined:target.dataset.prompt});
  else if(target.dataset.detailJob){const detail=await window.propertyWorker.getJobDetails(target.dataset.detailJob);$("detailPanel").classList.remove("is-hidden");$("detailContent").innerHTML=`<p><b>${detail.properties.length}</b> immobili · <b>${detail.people.length}</b> proprietari · <b>${detail.ownerships.length}</b> quote</p>${detail.properties.map(p=>`<div class="detail-group"><b>${esc(p.address??p.cadastral_key)}</b><small>${esc(p.cadastral_key)} · ${esc(p.processing_status)}</small></div>`).join("")}`;$("detailPanel").scrollIntoView({behavior:"smooth"})}
  else if(target.dataset.action==="close-detail")$("detailPanel").classList.add("is-hidden");
  else if(target.dataset.cancelJob)openCancel(target.dataset.cancelJob);
  else if(target.dataset.action==="cancel-current")openCancel(appState.activeJobId);
  else if(target.dataset.cancelDialog==="close"&&!cancelInFlight)$("cancelProcessDialog").close();
  else if(target.dataset.cancelDialog==="confirm"&&pendingCancelJobId){cancelInFlight=true;$("cancelProcessDialog").querySelectorAll("button").forEach(b=>b.disabled=true);await window.propertyWorker.cancelJob(pendingCancelJobId);$("cancelProcessDialog").close();toast("Lavorazione annullata")}
}catch(e){toast(e.message??String(e))}});

$("manualCorrectionForm").addEventListener("submit",async event=>{event.preventDefault();if(!resolutionDetail||!resolutionJobId)return;const properties=[...event.currentTarget.querySelectorAll("[data-property-id]")].map(section=>({id:section.dataset.propertyId,sheet:section.querySelector('[name="sheet"]').value,parcel:section.querySelector('[name="parcel"]').value,subaltern:section.querySelector('[name="subaltern"]').value,category:section.querySelector('[name="category"]').value,address:section.querySelector('[name="address"]').value||null,class:section.querySelector('[name="class"]').value||null,consistency:section.querySelector('[name="consistency"]').value||null,cadastralIncome:nullableNumber(section.querySelector('[name="cadastralIncome"]').value)}));const people=[...event.currentTarget.querySelectorAll("[data-person-id]")].map(section=>({id:section.dataset.personId,ownershipId:section.dataset.ownershipId,fullName:section.querySelector('[name="fullName"]').value,taxCode:section.querySelector('[name="taxCode"]').value||null,birthPlace:section.querySelector('[name="birthPlace"]').value||null,birthProvince:section.querySelector('[name="birthProvince"]').value||null,birthDate:section.querySelector('[name="birthDate"]').value||null,shareOriginal:section.querySelector('[name="shareOriginal"]').value,sharePercentage:nullableNumber(section.querySelector('[name="sharePercentage"]').value)}));try{await window.propertyWorker.saveManualCorrections({jobId:resolutionJobId,properties,people});$("manualCorrectionPanel").classList.add("is-hidden");toast("Correzioni salvate. Ora puoi riprendere il lavoro.")}catch(e){toast(e.message??String(e))}});
$("configurationForm").addEventListener("submit",async event=>{event.preventDefault();const data=new FormData(event.currentTarget);try{await window.propertyWorker.saveInternalConfiguration(Object.fromEntries(data));event.currentTarget.querySelector('[name="serviceRoleKey"]').value="";toast("Configurazione salvata e protetta") }catch(e){toast(e.message??String(e))}});
window.propertyWorker.onState(async state=>{appState=state;render();if(state.lastError&&state.activeJobId&&resolutionJobId!==state.activeJobId){try{await loadResolution(state.activeJobId,false)}catch{resolutionDetail=null}}});
window.propertyWorker.getState().then(async state=>{appState=state;render();if(state.lastError&&state.activeJobId)try{await loadResolution(state.activeJobId,false)}catch{resolutionDetail=null}}).catch(e=>toast(e.message??String(e)));
